    /// Deterministic pick for a level.
    static func puzzle(for difficulty: Difficulty, using generator: inout some RandomNumberGenerator) -> SlidingBlocksPuzzle {
        let idx = Int.random(in: 0..<30, using: &generator)
        let data = all[difficulty.level - 1][idx]
        return SlidingBlocksPuzzle(width: data.width, height: data.height, blocks: data.blocks, bigIndex: data.bigIndex)
    }

    /// Puzzles for a level without randomness (tests).
    static func puzzles(for level: Int) -> [PuzzleData] {
        precondition((1...10).contains(level))
        return all[level - 1]
    }
